/**
 * tinymce_wbce — plugins/fa_picker/plugin.min.js
 *
 * Font Awesome icon picker: opens a searchable icon grid, lets the user pick
 * size and color, and inserts `<i class="fa fa-name" style="...">` into the
 * content.
 *
 * The icon list is NOT hardcoded — it is parsed once from the bundled
 * Font Awesome stylesheet (all `.fa-*:before` classes), so it always matches
 * whatever FA version ships in include/font-awesome/. The stylesheet URL comes
 * in via the `fa_picker_css_url` option (set by include.php / the admin tool);
 * the same URL is injected into the host page (for the picker grid) and must
 * be part of content_css (for rendering inside the editor iframe — include.php
 * takes care of that).
 *
 * Renders via MicroModal (include/micromodal/) into document.body — same
 * approach and markup contract as plugins/link/plugin.min.js, so the dialog
 * is themed by modal.css through the shared --ws-* CSS variables and follows
 * the editor skin: a dark skin scopes [data-theme="dark"] onto the modal.
 * Only the icon grid gets a small plugin-specific style block (also --ws-*
 * based). MicroModal + modal.css are lazy-loaded once.
 *
 * The inserted <i> carries a zero-width space (​) so TinyMCE's serializer
 * does not strip it as an empty inline element — no verify_html:false needed.
 *
 * @license GNU GPL2
 */
(function () {
    'use strict';

    tinymce.PluginManager.add('fa_picker', function (editor) {

        editor.options.register('fa_picker_css_url',  { processor: 'string', default: '' });
        // Quick-pick swatches for the color field (resolved server-side:
        // icon palette → font-color palette → shared palette)
        editor.options.register('fa_picker_swatches', { processor: 'array', default: [] });

        var MODAL_ID = 'tmce-fa-picker';
        var STYLE_ID = 'tmce-fa-picker-style';

        function t(key, fallback) {
            var map = (window.TINYMCE_WBCE_I18N || {}).faPicker || {};
            return map[key] || fallback;
        }

        function esc(s) {
            return String(s == null ? '' : s)
                .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
        }

        // include/ base URL, derived from the FA stylesheet URL
        // (…/include/font-awesome/css/font-awesome.min.css → …/include)
        function includeUrl() {
            var url = editor.options.get('fa_picker_css_url');
            return url ? url.replace(/\/font-awesome\/.*$/, '') : '';
        }

        function loadCss(href) {
            if (document.querySelector('link[href="' + href + '"]')) { return; }
            var l = document.createElement('link');
            l.rel = 'stylesheet'; l.href = href;
            document.head.appendChild(l);
        }

        function loadScript(src) {
            return new Promise(function (resolve, reject) {
                var s = document.createElement('script');
                s.src = src;
                s.onload  = function () { resolve(); };
                s.onerror = function () { reject(new Error('script failed to load: ' + src)); };
                document.head.appendChild(s);
            });
        }

        // ── MicroModal + wbeColoris (lazy, once) ──────────────────────────────
        var depsPromise = null;
        function ensureDeps() {
            var inc = includeUrl();
            if (!inc) { return Promise.resolve(false); }
            // wbeSelect.css defines the --ws-* theme variables that modal.css
            // (and our grid styles) consume — without it the modal renders
            // transparent.
            loadCss(inc + '/wbeSelect/wbeSelect.css');
            loadCss(inc + '/micromodal/modal.css');
            loadCss(inc + '/wbeColoris/wbeColoris.css');
            loadCss(inc + '/wbeColoris/wbeColoris.admin.css');
            if (window.MicroModal && window.WbeColoris) { return Promise.resolve(true); }
            if (depsPromise) { return depsPromise; }
            depsPromise = Promise.all([
                window.MicroModal  ? null : loadScript(inc + '/micromodal/modal.min.js'),
                window.WbeColoris  ? null : loadScript(inc + '/wbeColoris/wbeColoris.js')
                    .then(function () { return loadScript(inc + '/wbeColoris/wbeColoris.i18n.js'); })
            ])
                .then(function () { return !!(window.MicroModal && window.WbeColoris); })
                .catch(function (err) {
                    console.error('[tinymce fa_picker]', err.message || err);
                    return !!window.MicroModal; // modal alone still works (text color field)
                });
            return depsPromise;
        }

        // ── Font Awesome CSS on the host page (needed to render the grid) ────
        function ensureFaCss() {
            var url = editor.options.get('fa_picker_css_url');
            if (url) { loadCss(url); }
        }

        // ── Icon list, parsed from the stylesheet (shared across editors) ────
        function loadIcons() {
            if (window.__tmceFaIcons) { return Promise.resolve(window.__tmceFaIcons); }
            var url = editor.options.get('fa_picker_css_url');
            if (!url) { return Promise.resolve([]); }
            return fetch(url)
                .then(function (r) { return r.text(); })
                .then(function (css) {
                    var seen = {}, names = [];
                    var re = /\.fa-([a-z0-9-]+):before/g, m;
                    while ((m = re.exec(css)) !== null) {
                        if (!seen[m[1]]) { seen[m[1]] = true; names.push(m[1]); }
                    }
                    names.sort();
                    window.__tmceFaIcons = names;
                    return names;
                })
                .catch(function (err) {
                    console.error('[tinymce fa_picker] failed to load icon list:', err);
                    return [];
                });
        }

        // ── Plugin-specific styles: only the grid — everything else is
        //    modal.css. Colors via --ws-* so they follow the theme. ──────────
        function ensureStyles() {
            if (document.getElementById(STYLE_ID)) { return; }
            var s = document.createElement('style');
            s.id = STYLE_ID;
            s.textContent = ''
                + '.fap-grid{overflow-y:auto;max-height:44vh;padding:4px 0;display:grid;'
                +   'grid-template-columns:repeat(auto-fill,minmax(42px,1fr));gap:4px;min-height:180px;'
                +   'scrollbar-width:thin;scrollbar-color:var(--ws-border) var(--ws-surface);}'
                + '.fap-grid::-webkit-scrollbar{width:10px;}'
                + '.fap-grid::-webkit-scrollbar-track{background:var(--ws-surface);}'
                + '.fap-grid::-webkit-scrollbar-thumb{background:var(--ws-border);border-radius:5px;border:2px solid var(--ws-surface);}'
                + '.fap-ic{border:1px solid transparent;border-radius:5px;background:none;cursor:pointer;'
                +   'font-size:19px;padding:8px 0;color:var(--ws-text);min-height:auto;min-width:0;margin:0;}'
                + '.fap-ic:hover{border-color:var(--ws-accent);background:var(--ws-accent-subtle);}'
                + '.fap-ic.sel{border-color:var(--ws-accent);background:var(--ws-accent-subtle);color:var(--ws-accent);}'
                + '.fap-empty{grid-column:1/-1;color:var(--ws-text-muted);font-size:13px;padding:20px;text-align:center;}'
                + '.fap-opts{display:flex;align-items:center;gap:12px;flex-wrap:wrap;margin-top:10px;}'
                + '.fap-opts .modal__label{padding:0 !important;display:inline-flex;align-items:center;gap:5px;}'
                + '.fap-size{width:64px !important;}'
                + '.fap-size-unit{width:60px;padding:4px 6px;border:1px solid var(--ws-border);'
                +   'border-radius:5px;background:var(--ws-bg);color:var(--ws-text);font-size:13px;min-height:34px;margin:0;}'
                + '.fap-color-txt{width:110px !important;font-family:var(--ws-font-mono);}'
                + '.fap-preview{flex:1;text-align:center;min-width:80px;color:var(--ws-text);font-size:26px;}'
                // Coloris floats its panel on document.body — lift it above the
                // modal overlay (z-index 99999 in modal.css)
                + '.clr-picker{z-index:100001 !important;}';
            document.head.appendChild(s);
        }

        // ── Dialog ────────────────────────────────────────────────────────────
        function openDialog() {
            ensureFaCss();
            ensureStyles();

            Promise.all([loadIcons(), ensureDeps()]).then(function (results) {
                var icons = results[0];
                if (!window.MicroModal) { return; }

                var existing = document.getElementById(MODAL_ID);
                if (existing) { existing.remove(); }

                var selected = '';
                // Default size unit mirrors the preset's font-size unit
                // (font_size_input_default_unit, set by include.php / tool)
                var defaultUnit = editor.options.get('font_size_input_default_unit') || 'px';
                if (['px', 'pt', 'em', 'rem'].indexOf(defaultUnit) === -1) { defaultUnit = 'px'; }

                var modal = document.createElement('div');
                modal.id = MODAL_ID;
                modal.className = 'modal micromodal-slide';
                modal.setAttribute('aria-hidden', 'true');
                // Follow the editor skin — same contract as the link plugin:
                // dark skin forces the dark --ws-* palette on this subtree.
                if (((editor.options.get('skin') || '')).indexOf('dark') !== -1) {
                    modal.setAttribute('data-theme', 'dark');
                }
                modal.innerHTML = ''
                    + '<div class="modal__overlay" tabindex="-1" data-micromodal-close>'
                    +   '<div class="modal__container" role="dialog" aria-modal="true" aria-labelledby="fap-title">'
                    +     '<header class="modal__header">'
                    +       '<h1 class="dialog__title" id="fap-title">' + esc(t('title', 'Insert Font Awesome icon')) + '</h1>'
                    +       '<button type="button" class="modal__close" data-micromodal-close aria-label="' + esc(t('cancel', 'Cancel')) + '">&times;</button>'
                    +     '</header>'
                    +     '<main class="modal__content">'
                    +       '<div class="tox-form__group">'
                    +         '<input type="text" class="tox-textfield fap-search" placeholder="' + esc(t('search', 'Search icons…')) + '">'
                    +       '</div>'
                    +       '<div class="fap-grid"></div>'
                    +       '<div class="fap-opts">'
                    +         '<label class="modal__label">' + esc(t('size', 'Size'))
                    +           ' <input type="number" class="tox-textfield fap-size" min="0" step="1">'
                    +           '<select class="fap-size-unit">'
                    +             ['px', 'pt', 'em', 'rem'].map(function (u) {
                                      return '<option value="' + u + '"' + (u === defaultUnit ? ' selected' : '') + '>' + u + '</option>';
                                  }).join('')
                    +           '</select></label>'
                    +         '<label class="modal__label">' + esc(t('color', 'Color'))
                    +           ' <input type="text" id="tmce-fap-color" class="tox-textfield fap-color-txt" data-wbecoloris placeholder="' + esc(t('inherit', 'inherit')) + '"></label>'
                    +         '<span class="fap-preview"></span>'
                    +       '</div>'
                    +     '</main>'
                    +     '<footer class="modal__footer">'
                    +       '<button type="button" class="modal__btn" data-micromodal-close>' + esc(t('cancel', 'Cancel')) + '</button>'
                    +       '<button type="button" class="modal__btn modal__btn-primary fap-insert" disabled>' + esc(t('insert', 'Insert')) + '</button>'
                    +     '</footer>'
                    +   '</div>'
                    + '</div>';
                document.body.appendChild(modal);

                var grid      = modal.querySelector('.fap-grid');
                var search    = modal.querySelector('.fap-search');
                var sizeInp   = modal.querySelector('.fap-size');
                var sizeUnit  = modal.querySelector('.fap-size-unit');
                var colorTxt  = modal.querySelector('.fap-color-txt');
                var preview   = modal.querySelector('.fap-preview');
                var insertBtn = modal.querySelector('.fap-insert');

                function renderGrid(filter) {
                    // Match against the full selector too: "fa-home", ".fa-home"
                    // and "fa fa-home" all find "home".
                    var q = (filter || '').toLowerCase().trim()
                        .replace(/^\./, '').replace(/^fa\s+/, '').replace(/^fa-/, '');
                    var html = '';
                    icons.forEach(function (name) {
                        if (q && name.indexOf(q) === -1) { return; }
                        html += '<button type="button" class="fap-ic' + (name === selected ? ' sel' : '') + '"'
                            + ' data-icon="' + name + '" title="fa-' + name + '">'
                            + '<i class="fa fa-' + name + '" aria-hidden="true"></i></button>';
                    });
                    grid.innerHTML = html || '<div class="fap-empty">' + esc(t('noResults', 'No icons found.')) + '</div>';
                }

                function sizeValue() {
                    var n = sizeInp.value.trim();
                    return (n !== '' && parseFloat(n) > 0) ? n + sizeUnit.value : '';
                }

                function updatePreview() {
                    if (!selected) { preview.innerHTML = ''; return; }
                    var style = '';
                    if (sizeValue())           { style += 'font-size:' + esc(sizeValue()) + ';'; }
                    if (colorTxt.value.trim()) { style += 'color:' + esc(colorTxt.value.trim()) + ';'; }
                    preview.innerHTML = '<i class="fa fa-' + selected + '" style="' + style + '" aria-hidden="true"></i>';
                }

                // Sensible number stepping per unit (0.1 for em/rem, 1 for px/pt)
                function syncStep() {
                    sizeInp.step = (sizeUnit.value === 'em' || sizeUnit.value === 'rem') ? '0.1' : '1';
                }
                syncStep();

                renderGrid('');

                search.addEventListener('input', function () { renderGrid(this.value); });
                grid.addEventListener('click', function (e) {
                    var btn = e.target.closest('.fap-ic');
                    if (!btn) { return; }
                    selected = btn.getAttribute('data-icon');
                    grid.querySelectorAll('.fap-ic.sel').forEach(function (el) { el.classList.remove('sel'); });
                    btn.classList.add('sel');
                    insertBtn.disabled = false;
                    updatePreview();
                });
                sizeInp.addEventListener('input', updatePreview);
                sizeUnit.addEventListener('change', function () { syncStep(); updatePreview(); });
                colorTxt.addEventListener('input', updatePreview);

                // wbeColoris on the color field — OK-button workflow, preset
                // swatches as quick picks, theme following the editor skin.
                if (window.WbeColoris) {
                    if (!window.__tmceFapColoris) {
                        window.__tmceFapColoris = true;
                        WbeColoris({
                            okButton: true,
                            format:   'hex',
                            alpha:    true,
                            onChange: function (color, input) {
                                if (input) input.dispatchEvent(new Event('input', { bubbles: true }));
                            }
                        });
                    }
                    WbeColoris.setInstance('#tmce-fap-color', {
                        themeMode: modal.getAttribute('data-theme') === 'dark' ? 'dark' : 'light',
                        swatches:  editor.options.get('fa_picker_swatches') || []
                    });
                    WbeColoris.wrap('#tmce-fap-color'); // adds the swatch preview button
                }

                insertBtn.addEventListener('click', function () {
                    if (!selected) { return; }
                    var style = '';
                    if (sizeValue())           { style += 'font-size: ' + sizeValue() + ';'; }
                    if (colorTxt.value.trim()) { style += ' color: ' + colorTxt.value.trim() + ';'; }
                    style = style.trim();
                    // ​ keeps the <i> non-empty so the serializer won't drop it
                    editor.insertContent(
                        '<i class="fa fa-' + selected + '"'
                        + (style ? ' style="' + esc(style) + '"' : '')
                        + ' aria-hidden="true">​</i>&nbsp;'
                    );
                    window.MicroModal.close(MODAL_ID);
                });

                window.MicroModal.show(MODAL_ID, {
                    disableScroll: true,
                    onClose: function (m) { m.remove(); }
                });
                search.focus();
            });
        }

        // Custom toolbar icon (wavy flag, echoing the FA motif)
        editor.ui.registry.addIcon('fa-flag', '<svg width="24" height="24" viewBox="0 0 24 24"><path d="M6.5 3.25a1 1 0 0 0-2 0V21h2v-6.03c1.6-.98 3.06-.92 4.68-.3 1.83.7 3.9 1.06 6.15-.42a1 1 0 0 0 .42-.84V5.02c0-.8-.9-1.27-1.55-.83-1.7 1.13-3.2.9-4.9.25-1.5-.57-3.16-.94-4.8-.3v-.9z" fill-rule="nonzero"/></svg>');

        editor.ui.registry.addButton('fa_picker', {
            icon: 'fa-flag',
            tooltip: 'Font Awesome icon',
            onAction: openDialog
        });

        editor.ui.registry.addMenuItem('fa_picker', {
            text: 'Font Awesome icon',
            icon: 'fa-flag',
            onAction: openDialog
        });

        return { getMetadata: function () { return { name: 'WBCE Font Awesome Picker' }; } };
    });
}());
